head.script:
// 테스트 설명, 유효성 값 설정
//  - column 샘플 관례 : textAlign 은 Body Column(상품명) 에만 설정 (설정 영역 con 옵션 미생성)
//  - 본 샘플(_2) : CSS 클래스 / setColumnStyle() / setCellStyle() 과의 우선순위 축
//  - 정렬값 축(left / center / right / 미설정) 은 column_P_textAlign_1, 편집 상태 입력창 정렬은 column_P_textAlign_3 소유
scwin.tData = {
    "description" : "[column > P > textAlign]<br/>Column 에 표시되는 텍스트의 가로 정렬 방법을 설정합니다.",
    "validation" : [
        "textAlign 속성값은 Cell('td') 요소의 style 에 text-align 으로 적용되므로 CSS 클래스에 정의한 text-align 보다 우선 적용됩니다.",
        "Body Column 에서 setColumnStyle(), setCellStyle() 메소드로 CSS 속성 'text-align' 을 설정하면 textAlign 속성값보다 우선 적용됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_textAlign.setValue("right");
    con_class.setValue("tc_textAlign_left");
    par_styleValue.setValue("left");
    par_rowIndex.setValue("0");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - textAlign(con 값) 과 class(con 값) 는 상품명(name) Body Column 에만 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] textAlign, Column class 는 상품명 Column 에만 설정 (tc_textAlign_left = CSS text-align:left, tc_textAlign_right = CSS text-align:right)\n[확인] Cell 정렬 확인 버튼 -> setColumnStyle / setCellStyle 실행 후 상품명 Column 의 Row 별 정렬 확인"', '', 'label1');

    let cTextAlign = con_textAlign.getValue();
    let cClass = con_class.getValue();

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cat" name="cat" dataType="text"></w2:column>';
    strDlt += '<w2:column id="price" name="price" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "무선 마우스", "cat" : "전자", "price" : 25000 },
        { "name" : "기계식 키보드", "cat" : "전자", "price" : 89000 },
        { "name" : "볼펜 세트", "cat" : "문구", "price" : 4500 },
        { "name" : "A4 복사용지", "cat" : "문구", "price" : 23000 }
    ], false);

    let attrName = '';
    if (cTextAlign !== '') {
        attrName += ' textAlign="' + cTextAlign + '"';
    }
    if (cClass !== '') {
        attrName += ' class="' + cClass + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="250" style="" inputType="text" id="h_name" value="상품명"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="h_cat" value="분류"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="h_price" value="가격"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="250" style="" id="name" inputType="text"' + attrName + '></w2:column>';
    strTarget += '<w2:column width="150" style="" id="cat" inputType="text"></w2:column>';
    strTarget += '<w2:column width="150" style="" id="price" inputType="text" dataType="number" displayFormat="#,###"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 상품명 Column 의 Row 별 정렬 상태 출력
//  - validation 1 : td class(CSS 클래스 text-align) 와 td style text-align / 계산된 text-align 대조
//  - validation 2 : setColumnStyle / setCellStyle 실행 후 td style text-align / 계산된 text-align
scwin.printAlign = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cTextAlign = con_textAlign.getValue();
    let cClass = con_class.getValue();
    let classAlign = { "tc_textAlign_left" : "left", "tc_textAlign_right" : "right" };
    bottom.setReturnValue("textAlign : " + (cTextAlign === '' ? "(미설정)" : cTextAlign) + " / Column class : " + (cClass === '' ? "(미설정)" : cClass + " (CSS text-align : " + classAlign[cClass] + ")"));

    for (let r = 0; r < target1.getRowCount(); r++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + r + "_0']");
        if (!td) {
            continue;
        }
        let hasClass = (cClass !== '' && td.classList.contains(cClass));
        bottom.setReturnValue("Row " + r + " : td 클래스 적용 = " + hasClass + ", td style text-align = " + (td.style.textAlign || "(없음)") + ", 계산된 text-align = " + getComputedStyle(td).textAlign);
    }
}



scwin.btn_checkAlign_onclick = function () {
    scwin.printAlign();
}



// setColumnStyle 실행 후 정렬 확인
scwin.btn_setColumnStyle_onclick = function () {
    let styleValue = par_styleValue.getValue();
    target1.setColumnStyle("name", "text-align", styleValue);
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnStyle('name', 'text-align', '" + styleValue + "') 실행");
    scwin.printAlign();
}



// setCellStyle 실행 후 정렬 확인
scwin.btn_setCellStyle_onclick = function () {
    let styleValue = par_styleValue.getValue();
    let rowIndex = Number(par_rowIndex.getValue());
    target1.setCellStyle(rowIndex, "name", "text-align", styleValue);
    wf_body_bottom.getObj("scwin").setReturnValue("setCellStyle(" + rowIndex + ", 'name', 'text-align', '" + styleValue + "') 실행");
    scwin.printAlign();
}
